function printTimingGroup(title,timings){let printableTimings=timings.filter(timing=>timing.ms>=0);if(printableTimings.length!==0){console.error(`
--- ${title} ---`);for(let t of printableTimings)console.error(`  ${t.label}: ${t.ms}ms`);console.error(`  TOTAL: ${printableTimings.reduce((a,b)=>a+b.ms,0)}ms`),console.error(`${"-".repeat(title.length+8)}
`)}}

